# -*- coding: utf-8 -*-
"""Glossary batch 6 — plasma drifts, transport, edge physics, electromagnetics."""
def register(cat, page, F):
    T = [
     ("loop-voltage","Loop Voltage","The toroidal voltage that drives and sustains ohmic plasma current.","The loop voltage is the electromotive force around the torus that drives current in the plasma. During start-up the central solenoid supplies it; a steady-state machine minimises it by relying on bootstrap and non-inductive current drive.",["plasma-current","central-solenoid","volt-seconds"]),
     ("volt-seconds","Volt-Seconds (Flux Swing)","The magnetic flux budget the solenoid spends to drive current.","Volt-seconds measure the flux the central solenoid can swing to induce and sustain plasma current. Limited solenoid space in a compact spherical tokamak makes the flux budget precious — one more reason non-inductive current drive matters.",["central-solenoid","loop-voltage","current-drive"]),
     ("spitzer-resistivity","Spitzer Resistivity","The classical electrical resistivity of a hot plasma, falling steeply with temperature.","A plasma's resistivity follows the Spitzer formula, dropping as temperature rises to the 3/2 power. Hotter plasmas are better conductors, so ohmic heating weakens at high temperature and auxiliary heating takes over.",["ohmic-heating","current-drive","plasma-current"]),
     ("ohmic-heating","Ohmic Heating","Heating from the plasma's own resistance to its current — effective only while the plasma is cool.","Driving current through a resistive plasma heats it, just like a filament. Because resistivity falls with temperature, ohmic heating alone cannot reach fusion temperatures, so machines add neutral beams and radio-frequency heating.",["spitzer-resistivity","heating-systems","electron-cyclotron-heating"]),
     ("magnetic-axis","Magnetic Axis","The innermost magnetic surface — the centre of the nested flux surfaces.","The magnetic axis is the central closed field line about which the flux surfaces nest. Plasma pressure and temperature usually peak there, and its position is tracked by magnetic diagnostics.",["magnetic-flux-surface","separatrix","magnetic-diagnostics"]),
     ("limiter","Limiter","A solid surface that defines the plasma edge in machines without a divertor.","A limiter is a plasma-facing surface that sets the last closed flux surface by physical contact, an alternative to a divertor. Most modern power-plant designs use divertors for better exhaust handling.",["divertor","separatrix","scrape-off-layer"]),
     ("single-null","Single-Null Configuration","A divertor layout with one X-point, the common power-plant choice.","A single-null plasma has one X-point directing exhaust to one divertor. It is mechanically simpler than a double-null and is a standard power-plant configuration.",["x-point","double-null","divertor"]),
     ("double-null","Double-Null Configuration","A symmetric layout with two X-points that shares the exhaust load.","A double-null plasma has X-points top and bottom, splitting the exhaust between two divertors and adding up-down symmetry, at the cost of control complexity.",["single-null","x-point","divertor"]),
     ("connection-length","Connection Length","The distance along a field line from the outer midplane to the divertor target.","The connection length is how far edge plasma travels along field lines before reaching the target. Longer connection lengths give more room for the plasma to radiate and cool, aiding detachment.",["scrape-off-layer","detachment","parallel-heat-flux"]),
     ("parallel-heat-flux","Parallel Heat Flux","The intense heat flowing along field lines toward the divertor.","Heat flows overwhelmingly along field lines, arriving at the divertor as an intense parallel flux that must be spread and cooled. Managing it is the central divertor challenge, addressed by radiation and detachment.",["heat-flux","detachment","connection-length"]),
     ("plasma-sheath","The Plasma Sheath","The thin charged layer where plasma meets a solid surface.","At any material surface a thin sheath forms where the plasma potential drops sharply, accelerating ions into the surface. Sheath physics sets the heat and particle load on plasma-facing components.",["plasma-facing-materials","neutral-recycling","floating-potential"]),
     ("floating-potential","Floating Potential","The voltage an isolated surface floats to in contact with plasma.","An electrically isolated surface in a plasma charges until it repels enough electrons to balance the ion flux — its floating potential. It underlies Langmuir-probe diagnostics and sheath heat loads.",["plasma-sheath","langmuir-probe","plasma-diagnostics"]),
     ("langmuir-probe","Langmuir Probe","A simple biased electrode that measures edge density and temperature.","A Langmuir probe is a small electrode swept in voltage; its current-voltage curve yields the local electron density and temperature. It is a workhorse edge diagnostic.",["floating-potential","plasma-diagnostics","scrape-off-layer"]),
     ("charge-exchange","Charge Exchange","A neutral and an ion swapping an electron — important for edge losses and diagnostics.","In charge exchange, a neutral atom hands an electron to an ion, creating a fast neutral that can escape the plasma. It drives edge energy losses and enables certain temperature diagnostics.",["neutral-recycling","spectroscopy","fast-ions"]),
     ("ionization","Ionization","Stripping electrons from atoms to form plasma — the process that fuels the edge.","Ionization frees electrons from atoms, sustaining the plasma as neutrals recycle from the wall. The balance of ionization and recombination shapes the edge and divertor.",["neutral-recycling","recombination","plasma"]),
     ("recombination","Recombination","Ions and electrons recombining into neutrals — key to divertor detachment.","When plasma cools enough, ions and electrons recombine into neutral atoms, removing charged particles and heat. Volume recombination is central to a detached, protected divertor.",["detachment","ionization","radiative-divertor"]),
     ("exb-drift","E&times;B Drift","A universal plasma drift set by crossed electric and magnetic fields.","Charged particles in crossed electric and magnetic fields drift perpendicular to both at the same velocity regardless of charge — the E&times;B drift. It governs plasma rotation and edge flows.",["plasma-rotation","curvature-drift","guiding-center"]),
     ("curvature-drift","Curvature & Gradient Drifts","Charge-dependent drifts from field curvature and gradients that must be cancelled to confine.","Field-line curvature and magnetic-field gradients cause ions and electrons to drift in opposite directions, which would separate charge and destroy confinement in a straight field. The tokamak's twist and the mirror's shaping cancel these drifts.",["exb-drift","guiding-center","rotational-transform"]),
     ("guiding-center","Guiding-Center Motion","The averaged drift of a particle's gyration, the basis of confinement theory.","Rather than track a particle's fast spiral, guiding-center theory follows the slow drift of its orbit centre. It is the framework in which drifts, trapping and neoclassical transport are understood.",["larmor-radius","trapped-particles","curvature-drift"]),
     ("adiabatic-invariant","Adiabatic Invariant","A nearly-conserved quantity (the magnetic moment) that underlies mirror confinement.","A charged particle's magnetic moment is conserved as it moves through slowly-varying fields. This invariance is exactly what reflects particles from a magnetic mirror's high-field throats.",["magnetic-mirror","mirror-ratio","guiding-center"]),
     ("quasineutrality","Quasineutrality","A plasma's tendency to keep equal ion and electron densities over any appreciable scale.","Beyond the tiny Debye length, a plasma maintains nearly equal positive and negative charge densities; any imbalance sets up strong restoring fields. Quasineutrality underlies the ambipolar physics that plugs the tandem mirror.",["debye-length","ambipolar-potential","plasma-frequency"]),
     ("density-limit","The Density Limit","The maximum density before radiative collapse or disruption.","Push a tokamak's density too high and edge cooling or the Greenwald limit triggers a radiative collapse or disruption. Kronos operates within the limit; the mirror burner is not subject to it.",["greenwald-density","radiative-collapse","disruptions"]),
     ("radiative-collapse","Radiative Collapse","A runaway cooling of the plasma edge that can end a discharge.","If edge radiation exceeds the heating reaching the edge, the plasma cools, shrinks and can disrupt — a radiative collapse. Controlled radiation (for divertor protection) must stay short of this runaway.",["density-limit","radiated-power-fraction","disruptions"]),
     ("power-threshold","H-mode Power Threshold","The minimum heating power needed to access high-confinement mode.","H-mode only appears above a heating-power threshold that scales with density, field and size. A machine's heating must comfortably exceed it to operate in the high-confinement regime.",["l-h-transition","h-mode","heating-systems"]),
     ("particle-pinch","Particle Pinch","An inward transport that peaks the density profile, aiding fusion power.","Beyond simple diffusion, turbulence and neoclassical effects can drive particles inward — a pinch — peaking the density where the plasma is hottest and boosting fusion power.",["density-peaking","turbulent-transport","neoclassical-transport"]),
     ("thermal-diffusivity","Thermal Diffusivity","How fast heat diffuses across the field — the quantity confinement minimises.","Thermal diffusivity measures cross-field heat transport; lower values mean better confinement. It is dominated by turbulence and is what empirical scaling laws effectively summarise.",["turbulent-transport","confinement-scaling","energy-confinement-time"]),
     ("critical-gradient","Critical-Gradient Transport","Turbulence that switches on above a threshold gradient, stiffening profiles.","Many plasma instabilities turn on sharply above a critical temperature gradient, clamping the profile near that threshold ('stiffness'). This shapes how core temperature responds to heating.",["itg-mode","turbulent-transport","profile-stiffness"]),
     ("itg-mode","Ion-Temperature-Gradient Mode","A key micro-instability driving ion heat transport.","The ion-temperature-gradient (ITG) mode is a leading drift-wave instability that transports ion heat outward once the temperature gradient exceeds a threshold. It is a primary target of turbulence suppression.",["drift-wave","critical-gradient","turbulent-transport"]),
     ("profile-stiffness","Profile Stiffness","The resistance of temperature profiles to being pushed past critical gradients.","Because turbulence clamps gradients near a threshold, temperature profiles are 'stiff' — extra core heating raises the whole profile rather than steepening it. Edge conditions (the pedestal) then strongly set core performance.",["critical-gradient","pedestal","itg-mode"]),
     ("zonal-flow","Zonal Flows","Self-generated sheared flows that regulate plasma turbulence.","Turbulence itself drives sheared 'zonal' flows that then shear apart the turbulent eddies, a self-regulating feedback that sets transport levels. Understanding it is central to predicting confinement.",["turbulent-transport","drift-wave","plasma-rotation"]),
     ("ideal-mhd","Ideal MHD","The zero-resistivity limit used to test a plasma's gross stability.","Ideal magnetohydrodynamics treats the plasma as a perfectly conducting fluid to test fast, large-scale stability — kinks and ballooning modes. Passing ideal-MHD limits is a first stability hurdle every design must clear.",["mhd-stability","ballooning-modes","kink-instability"]),
     ("resistive-mhd","Resistive MHD","MHD with finite resistivity, allowing tearing and reconnection.","Adding resistivity to MHD allows field lines to break and reconnect, giving tearing modes and slower instabilities that ideal theory misses. It is needed to assess neoclassical tearing modes and disruptions.",["ideal-mhd","tearing-mode","magnetic-reconnection"]),
     ("energetic-particle-mode","Energetic-Particle Modes","Instabilities driven by fast ions, distinct from Alfvén eigenmodes.","Beyond Alfvén eigenmodes, fast ions can drive their own energetic-particle modes that redistribute or expel them. Keeping the fast-ion population well confined is essential for heating and, in D–T, alpha confinement.",["fast-ions","alfven-eigenmodes","fishbone-instability"]),
     ("geodesic-acoustic-mode","Geodesic Acoustic Mode","An oscillating branch of zonal flow seen in the plasma edge.","The geodesic acoustic mode is an oscillating cousin of the zonal flow, part of the turbulence-regulation machinery in the plasma edge. It appears in turbulence measurements and simulations.",["zonal-flow","turbulent-transport","drift-wave"]),
     ("marfe","MARFE","A radiating edge instability that can precede a density-limit disruption.","A MARFE is a localized band of intense edge radiation that forms near the density limit, cooling and constricting the plasma. It is a warning sign managed by density and impurity control.",["density-limit","radiative-collapse","impurity-seeding"]),
     ("qh-mode","Quiescent H-mode","A high-confinement regime without large ELMs.","Quiescent H-mode sustains a strong edge pedestal without the large, damaging ELMs, using edge flows and modes to exhaust energy smoothly. It is one of several ELM-free regimes of interest for protecting the divertor.",["edge-localized-modes","pedestal","negative-triangularity"]),
     ("i-mode","I-mode","A regime with a hot pedestal but L-mode-like density and no ELMs.","I-mode decouples energy and particle transport, giving a temperature pedestal (good confinement) without a density pedestal or ELMs. It is another candidate for benign edge operation.",["h-mode","pedestal","edge-localized-modes"]),
     ("lambda-q","Divertor Heat-Flux Width","The narrow width over which exhaust heat strikes the target.","The scrape-off-layer heat-flux width sets how concentrated the divertor load is; a narrow width means a fierce peak flux. It drives divertor design and the case for radiative, detached operation.",["parallel-heat-flux","scrape-off-layer","detachment"]),
     ("sol-flow","Scrape-Off-Layer Flows","Plasma flows along open field lines that redistribute heat and particles.","Flows along the open field lines of the scrape-off layer move heat and particles toward the divertor and between its legs, influencing where the load lands and how impurities move.",["scrape-off-layer","parallel-heat-flux","neutral-recycling"]),
     ("plasma-elongation-control","Vertical Stability Control","Active feedback that holds an elongated plasma in place.","Elongated plasmas are vertically unstable and drift up or down without fast feedback control from dedicated coils. Robust vertical control is essential for HYPERION's &kappa; = "+F['b_kappa']+" shape.",["elongation","vertical-displacement-event","magnetic-diagnostics"]),
     ("plasma-position-control","Plasma Position & Shape Control","Real-time control of where the plasma sits and how it is shaped.","A control system continuously adjusts the poloidal-field coils to hold the plasma's position and shape against disturbances, using magnetic diagnostics as its eyes. It is core to safe, reproducible operation.",["magnetic-diagnostics","instrumentation-control","plasma-shaping"]),
     ("real-time-control","Real-Time Plasma Control","The fast feedback system that keeps the plasma stable millisecond to millisecond.","A real-time control system fuses diagnostics and actuators — heating, fuelling, coils — to hold the plasma at its operating point and head off instabilities. It is where plasma physics meets control engineering.",["plasma-position-control","instrumentation-control","real-time-control"][:2]+["disruption-mitigation"]),
     ("actuator","Plasma Actuators","The knobs — heating, fuelling, current drive, coils — a control system turns.","Actuators are the means by which control acts on the plasma: heating and current-drive power, fuelling rate, gas and impurity injection, and coil currents. Their range and speed bound what control can achieve.",["real-time-control","heating-systems","gas-puffing"]),
     ("plasma-startup-scenario","Operating Scenario","The planned trajectory of current, density and heating through a discharge.","An operating scenario is the pre-planned path a discharge follows from start-up through flat-top to ramp-down, chosen to stay stable and reach the design point. Scenario design is a core part of preparing to operate.",["tokamak-startup","flat-top","steady-state-operation"]),
     ("burn-control","Burn Control","Regulating fusion power by adjusting fuelling and heating.","Burn control keeps fusion power at its set point by trimming fuelling and heating — straightforward in a driven machine, where turning the heating down turns the power down. It is what makes a driven design controllable.",["ignition-vs-driven","actuator","dispatchable-power"]),
     ("fuel-ratio-control","Fuel Mixture Control","Holding the right isotope or D-to-&sup3;He ratio for optimum reactivity.","Fusion power depends on the fuel mix — the D–T ratio in the breeder, the D-to-&sup3;He ratio (x = "+F['u_x']+") in the burner. Controlling it maintains peak reactivity and is part of the fuelling system's job.",["d-he3-fuel","reactivity","fuel-cycle"]),
     ("plasma-diagnostics-suite","The Diagnostic Suite","The full ensemble of instruments that together measure the plasma state.","No single instrument measures everything; a machine carries a coordinated suite — magnetics, Thomson scattering, interferometry, spectroscopy, bolometry, neutron detectors — whose combined output feeds control and validation.",["plasma-diagnostics","thomson-scattering","real-time-control"]),
     ("shot","Discharge (Shot)","A single plasma pulse — the unit of tokamak experimentation.","A 'shot' is one plasma discharge, from breakdown to termination. Experimental machines are characterised by their shot count and reproducibility; a power plant must string continuous operation together instead.",["first-plasma","flat-top","duty-cycle"]),
    ]
    for slug,term,one,para,rel in T:
        page(slug,term,"glossary",one,one,[('p',para)],related=rel,jtype="DefinedTerm",kicker="Glossary")
